// Invariants of the Mundinho character and creature sprites (npm run test:mundinho-sprites).
// The art itself is generated by scripts/mundinho-sprites and authored hero layers; this check
// guards the rules the game code relies on.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import sharp from 'sharp';
import { poses, directions } from './lib/tutorial-player.mjs';
import { ASSETS } from './mundinho-sprites/assets.mjs';
const root = 'public/assets/mundinho';
const hairstyles = JSON.parse(fs.readFileSync('src/lib/mundinho/hairstyles.json', 'utf8'));
assert.deepEqual(
  hairstyles.map((style) => style.id),
  Array.from({ length: hairstyles.length }, (_, i) => i)
);
const palette = new Set(
  JSON.parse(fs.readFileSync('artifacts/mundinho/libresprite-v2/palette-aap-64.json', 'utf8'))
);
async function load(name) {
  return sharp(`${root}/${name}.png`).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
}

const heroes = ASSETS.filter((a) => a.name.startsWith('hero-'));
function crop(sheet, v, d, f) {
  const pixels = Buffer.alloc(48 * 48 * 4);
  for (let y = 0; y < 48; y++) {
    const start = (((v * 4 + d) * 48 + y) * sheet.info.width + f * 48) * 4;
    sheet.data.copy(pixels, y * 48 * 4, start, start + 48 * 4);
  }
  return pixels;
}
// A dyed bun or spike must touch the dyed crown even against a black background.
function assertRootedHair(base, cut, label) {
  const pending = [],
    seen = new Uint8Array(48 * 48);
  for (let i = 0; i < seen.length; i++)
    if (base[i * 4 + 3] && cut[i * 4 + 3]) {
      pending.push(i);
      seen[i] = 1;
    }
  while (pending.length) {
    const i = pending.pop();
    for (const n of [i - 1, i + 1, i - 48, i + 48]) {
      if (n >= 0 && n < seen.length && !seen[n] && cut[n * 4 + 3]) {
        seen[n] = 1;
        pending.push(n);
      }
    }
  }
  for (let i = 0; i < seen.length; i++)
    if (cut[i * 4 + 3]) assert.ok(seen[i], label + ' detached hair pixel ' + i);
}
for (const [motion, pose] of Object.entries(poses)) {
  const suffix = motion === 'walk' ? '' : '-' + motion;
  const layers = [
    'body',
    'outfit',
    'eyes',
    'hair',
    'accessory',
    ...(['attack', 'bow'].includes(motion) ? ['weapon'] : []),
  ];
  const sheets = await Promise.all(layers.map((l) => load('hero-' + l + suffix)));
  for (const [i, sheet] of sheets.entries()) {
    const asset = heroes.find((a) => a.name === 'hero-' + layers[i] + suffix);
    assert.equal(sheet.info.height, asset.height);
    assert.equal(sheet.info.width, 288);
  }
  for (let d = 0; d < 4; d++) {
    const source = await sharp(
      'artifacts/mundinho/tutorial-source/spr_personagem_' +
        pose.source +
        '_' +
        directions[d] +
        '_strip6.png'
    )
      .ensureAlpha()
      .raw()
      .toBuffer({ resolveWithObject: true });
    const width = source.info.width / 6;
    for (let f = 0; f < 6; f++) {
      const frames = sheets.map((sheet, i) =>
        crop(sheet, i === 0 || layers[i] === 'weapon' ? 2 : 0, d, f)
      );
      const actual = Buffer.alloc(48 * 48 * 4),
        expected = Buffer.alloc(actual.length);
      for (const frame of frames)
        for (let i = 0; i < frame.length; i += 4) if (frame[i + 3]) frame.copy(actual, i, i, i + 4);
      const [left, top] = pose.origins[d];
      for (let y = 0; y < source.info.height; y++)
        for (let x = 0; x < width; x++) {
          const i = (y * source.info.width + f * width + x) * 4;
          if (source.data[i + 3])
            source.data.copy(expected, ((y + top) * 48 + left + x) * 4, i, i + 4);
        }
      assert.ok(
        actual.equals(expected),
        motion + ' direction ' + d + ' frame ' + f + ' must reproduce the supplied PNG'
      );
      const hairSheet = sheets[layers.indexOf('hair')],
        base = crop(hairSheet, 3, d, f);
      for (const style of hairstyles.slice(1))
        assertRootedHair(
          base,
          crop(hairSheet, style.id * 6 + 3, d, f),
          motion + ' ' + d + ' ' + f + ' ' + style.name
        );
      for (let outfit = 0; outfit < 12; outfit++)
        assert.ok(
          crop(sheets[1], outfit, d, f).equals(crop(sheets[1], outfit + 12, d, f)),
          'shared trouser silhouette'
        );
      const pupils = crop(sheets[layers.indexOf('eyes')], 0, d, f);
      for (const [layer, variants] of [
        ['hair', 54],
        ['accessory', 6],
      ]) {
        const sheet = sheets[layers.indexOf(layer)];
        for (let variant = 0; variant < variants; variant++) {
          const overlay = crop(sheet, variant, d, f);
          for (let i = 3; i < pupils.length; i += 4)
            if (pupils[i])
              assert.equal(
                overlay[i],
                0,
                motion + ' ' + d + ' ' + f + ' ' + layer + ' ' + variant + ' covers a pupil'
              );
        }
      }
      assert.notDeepEqual(crop(sheets[0], 2, d, f), crop(sheets[0], 11, d, f), 'feminine variant');
    }
    const hair = sheets[layers.indexOf('hair')];
    assert.equal(
      new Set(hairstyles.map((_, n) => crop(hair, n * 6, d, 0).toString('hex'))).size,
      hairstyles.length
    );
  }
}
const aapAssets = new Set([
  'creatures-animated',
  'forest-ground',
  'forest-scenery',
  'habitats-back',
  'habitats-front',
]);
const generated = [
  ...heroes.map((a) => a.name),
  'creatures-animated',
  'forest-ground',
  'forest-scenery',
  'habitats-back',
  'habitats-front',
  'portrait-hair-back',
  'portrait-body',
  'portrait-outfit',
  'portrait-eyes',
  'portrait-hair',
  'portrait-accessory',
];
for (const name of generated) {
  const { data } = await load(name);
  for (let i = 0; i < data.length; i += 4) {
    if (!data[i + 3]) continue;
    assert.equal(data[i + 3], 255, `${name}: semi-transparent pixel`);
    const hex = [data[i], data[i + 1], data[i + 2]]
      .map((v) => v.toString(16).padStart(2, '0'))
      .join('');
    if (aapAssets.has(name)) assert.ok(palette.has(hex), `${name}: #${hex} is outside AAP-64`);
  }
}

for (const [name, count] of Object.entries({
  'portrait-body': 18,
  'portrait-outfit': 24,
  'portrait-eyes': 10,
  'portrait-hair': hairstyles.length,
  'portrait-hair-back': hairstyles.length,
  'portrait-accessory': 6,
})) {
  const { info } = await load(name);
  assert.equal(info.width, 96 * count, `${name}: saved variant count`);
  assert.equal(info.height, 112, `${name}: portrait layer alignment`);
}
const portraitHair = await load('portrait-hair');
const portraitStyles = hairstyles.map((_, style) => {
  const rows = [];
  for (let y = 0; y < 112; y++) {
    const start = (y * portraitHair.info.width + style * 96) * 4;
    rows.push(portraitHair.data.subarray(start, start + 96 * 4));
  }
  return Buffer.concat(rows).toString('hex');
});
assert.equal(
  new Set(portraitStyles).size,
  hairstyles.length,
  'every hairstyle has a matching portrait'
);
// Every portrait garment covers the torso. The skin layer must not extend beyond
// its sleeves, including the narrower feminine shoulders and sailor uniform.
const portraitBody = await load('portrait-body');
const portraitOutfit = await load('portrait-outfit');
for (let silhouette = 0; silhouette < 2; silhouette++)
  for (let skin = 0; skin < 9; skin++) {
    const bodyFrame = silhouette * 9 + skin;
    const neckAlpha =
      portraitBody.data[(78 * portraitBody.info.width + bodyFrame * 96 + 48) * 4 + 3];
    assert.equal(neckAlpha, 255, `portrait skin ${skin}: neck remains connected`);
    for (let outfit = 0; outfit < 12; outfit++) {
      const outfitFrame = silhouette * 12 + outfit;
      for (let y = 84; y < 112; y++)
        for (let x = 0; x < 96; x++) {
          if (x >= 34 && x <= 62) continue; // The neckline may intentionally expose the neck.
          const bodyAlpha =
            portraitBody.data[(y * portraitBody.info.width + bodyFrame * 96 + x) * 4 + 3];
          if (!bodyAlpha) continue;
          const outfitAlpha =
            portraitOutfit.data[(y * portraitOutfit.info.width + outfitFrame * 96 + x) * 4 + 3];
          assert.equal(
            outfitAlpha,
            255,
            `portrait silhouette ${silhouette}, skin ${skin}, outfit ${outfit}: exposed skin outside sleeve at ${x},${y}`
          );
        }
    }
  }
console.log(
  'Verified all 96 original player poses pixel-for-pixel, feminine variants, hairstyles, portraits and scenery.'
);
